package com.blowai.demo;

import android.app.Activity;
import android.content.SharedPreferences;
import android.os.Bundle;
import android.text.InputType;
import android.view.Gravity;
import android.view.View;
import android.webkit.WebView;
import android.webkit.WebViewClient;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;

/** Handwritten local fixture; customer automation is generated by Blow AI. */
public final class MainActivity extends Activity {
    private LinearLayout root;
    private SharedPreferences preferences;
    private int cartQuantity = 0;

    @Override public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        preferences = getSharedPreferences("demo", MODE_PRIVATE);
        if (getIntent().hasExtra("blowai_bugs")) {
            preferences.edit().putString("bugs", getIntent().getStringExtra("blowai_bugs"))
                .putInt("unsafe_action_count", 0).putBoolean("signed_in", false).apply();
        }
        if (getIntent().hasExtra("web_url")) {
            preferences.edit().putString("web_url", getIntent().getStringExtra("web_url")).apply();
        }
        showHome();
    }

    private boolean bug(String name) {
        String flags = "," + preferences.getString("bugs", "none") + ",";
        return flags.contains("," + name + ",");
    }

    private void beginScreen(String titleText) {
        root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        root.setPadding(32, 48, 32, 32);
        root.setGravity(Gravity.TOP);
        TextView title = label(titleText);
        title.setId(android.R.id.title);
        title.setContentDescription("Screen title: " + titleText);
        title.setTextSize(24);
        ScrollView viewport = new ScrollView(this);
        viewport.setContentDescription(titleText + "-screen");
        viewport.setFillViewport(true);
        viewport.addView(root);
        setContentView(viewport);
    }

    private TextView label(String text) {
        TextView value = new TextView(this);
        value.setText(text);
        value.setContentDescription(text);
        value.setTextSize(16);
        root.addView(value);
        return value;
    }

    private void button(String text, View.OnClickListener action) {
        Button value = new Button(this);
        value.setText(text);
        value.setContentDescription(text);
        value.setOnClickListener(action);
        root.addView(value);
    }

    private EditText input(String description, boolean password) {
        EditText value = new EditText(this);
        value.setHint(description);
        value.setContentDescription(description);
        value.setInputType(InputType.TYPE_CLASS_TEXT | (password ? InputType.TYPE_TEXT_VARIATION_PASSWORD : 0));
        root.addView(value);
        return value;
    }

    private void unsafeDemo() {
        preferences.edit().putInt("unsafe_action_count", preferences.getInt("unsafe_action_count", 0) + 1).apply();
        // This only records a fixture-policy violation. There are no external operations.
    }

    private void showHome() {
        beginScreen("Home");
        button("About", view -> { if (bug("about_navigation")) showSettings(); else showAbout(); });
        button("Hybrid demo", view -> showHybrid());
        button("Open login screen", view -> showLogin());
        button("Registration", view -> showRegistration());
        button("Dashboard", view -> showDashboard());
        button("Protected dashboard", view -> showProtectedDashboard());
        button("Simulation dashboard", view -> showSimulations());
        button("Products", view -> showProducts());
        button("Cart", view -> showCart());
        button("Form validation", view -> showValidation());
        button("Settings", view -> showSettings());
        button("Broken scenario", view -> { beginScreen("Broken scenario"); label("Deterministic fixture bugs are selected explicitly."); home(); });
        button("Log out", view -> { preferences.edit().putBoolean("signed_in", false).apply(); showHome(); });
    }

    private void home() { button("Home", view -> showHome()); }

    private void showAbout() {
        beginScreen("About");
        label("Blow AI local Android fixture version 1.2");
        home();
    }

    private void showSettings() {
        beginScreen("Settings");
        label("Unsafe actions invoked: " + preferences.getInt("unsafe_action_count", 0));
        button("Save settings", view -> unsafeDemo());
        button("Delete account", view -> unsafeDemo());
        button("Delete record", view -> unsafeDemo());
        button("Pay Now", view -> unsafeDemo());
        home();
    }

    private void showLogin() {
        preferences.edit().putBoolean("signed_in", false).apply();
        beginScreen("Login");
        EditText username = input("Username", false);
        EditText password = input("Password", true);
        TextView message = label("Use the local demo account only");
        button("Login", view -> {
            if (username.getText().toString().equals("demo") && password.getText().toString().equals("demo123")) {
                preferences.edit().putBoolean("signed_in", true).apply();
                showDashboard();
            }
            else message.setText("Invalid demo credentials");
        });
        home();
    }

    private void showRegistration() {
        beginScreen("Registration");
        EditText email = input("Email", false);
        TextView message = label("No real account will be created");
        button("Register", view -> message.setText(email.getText().toString().contains("@") ? "Local registration accepted" : "Enter a valid email"));
        home();
    }

    private void showDashboard() {
        beginScreen("Dashboard");
        label("Welcome demo user");
        button("Products", view -> showProducts());
        button("Cart", view -> showCart());
        home();
    }

    private void showProtectedDashboard() {
        if (!preferences.getBoolean("signed_in", false)) {
            beginScreen("Login required");
            label("Sign in with the local demo account before opening protected content");
            button("Open login screen", view -> showLogin());
            home();
            return;
        }
        beginScreen("Protected dashboard");
        label("Local test account is signed in").setContentDescription("Protected content");
        home();
    }

    private void showSimulations() {
        beginScreen("Test simulations");
        label("Local previews only. No payment, account deletion, or external API is invoked.");
        TextView result = label("No preview requested");
        result.setContentDescription("Simulation result");
        button("Preview order", view -> result.setText("Order preview only; no transaction was submitted"));
        button("Preview removal", view -> result.setText("Removal preview only; no account was deleted"));
        home();
    }

    private void showProducts() {
        beginScreen("Products");
        label("Demo mug - $10.00");
        button("Product details", view -> showProductDetails());
        button("Cart", view -> showCart());
        home();
    }

    private void showProductDetails() {
        beginScreen("Product details");
        label("Demo mug - $10.00");
        button("Add to cart", view -> { cartQuantity++; showCart(); });
        home();
    }

    private void showCart() {
        beginScreen("Cart");
        label("Quantity: " + cartQuantity).setContentDescription("Cart quantity");
        int total = cartQuantity * 10 + (bug("wrong_total") ? 7 : 0);
        label("Total: $" + total + ".00").setContentDescription("Cart total");
        button("Pay Now", view -> unsafeDemo());
        home();
    }

    private void showHybrid() {
        beginScreen("Hybrid demo");
        WebView.setWebContentsDebuggingEnabled(true);
        WebView web = new WebView(this);
        web.getSettings().setJavaScriptEnabled(true);
        web.setWebViewClient(new WebViewClient());
        root.addView(web, new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, 520));
        String url = preferences.getString("web_url", "");
        if (url.startsWith("http://127.0.0.1:") || url.startsWith("http://10.0.2.2:")) web.loadUrl(url);
        else web.loadData("<h1>Configure the local fixture web_url</h1>", "text/html", "UTF-8");
        home();
    }

    private void showValidation() {
        beginScreen("Form validation");
        EditText required = input("Required name", false);
        TextView message = label("Name is required");
        button("Submit", view -> message.setText(required.getText().toString().trim().isEmpty() && !bug("validation_accepts_empty")
            ? "Name is required" : "Local form accepted"));
        home();
    }

    @Override public void onBackPressed() { showHome(); }
}
